/** services.device.verified: Staff verify a registered device */
export interface ServicesDeviceVerifiedEvent {
  deviceId: string;
  /** customers-module id (the account id for an account without a customer record) */
  customerId: string;
  label: string;
  coveredUntil: string;
}

export const ServicesDeviceVerifiedEvent: z.ZodType<ServicesDeviceVerifiedEvent> = z.object({
  deviceId: z.uuid(),
  customerId: z.uuid().describe("customers-module id (the account id for an account without a customer record)"),
  label: z.string(),
  coveredUntil: z.iso.date(),
});

/** services.device.rejected: Staff reject a registered device or withdraw its verification */
export interface ServicesDeviceRejectedEvent {
  deviceId: string;
  customerId: string;
  label: string;
  reason: string;
}

export const ServicesDeviceRejectedEvent: z.ZodType<ServicesDeviceRejectedEvent> = z.object({
  deviceId: z.uuid(),
  customerId: z.uuid(),
  label: z.string(),
  reason: z.string(),
});

/* ------------------------------------------------------------------ public API (in-process) */

/** What other modules may call in-process: `ctx.use('services')` (or `ctx.tryUse` for an optional dependency). */
export interface ServicesPublicApi {
  /** The customer's service requests and bookings (reference, service, provider, time, contact, details, device, status history), reviews, saved providers and registered devices (with the full IMEI) for the personal data export. Requests and reviews are found by the account id, saved providers and devices by the customers-module id (and the account id they fall back to). Staff notes are left out. Used by: customers. */
  exportCustomerData(input: { customerId: string, accountId: string }): Promise<common.CustomerDataSection[]>;
}

/* ------------------------------------------------------------------ tables (row types) */

/** Rows of this module's spec tables, as repositories read them from its collections (`services.<table>`, ctx.mongo.table(name)). */
export interface ServicesDb {
  categories: {
    id: string;
    area: string;
    slug: string;
    name: string;
    icon: string | null;
    position: number;
    visible: boolean;
  };
  providers: {
    id: string;
    slug: string;
    name: string;
    logo: Json | null;
    cover: Json | null;
    kind: string | null;
    category_id: string | null;
    city: string | null;
    verified: boolean;
    photos: Json;
    description: string | null;
    since: number | null;
    contacts: Json;
    location: Json | null;
    /** the address geocoded when there is no pin */
    point: Json | null;
    hours: Json;
    staff: Json;
    reply_time: string | null;
    status: string;
    rating_sum: number;
    rating_count: number;
    rating_stars: Json;
    created_at: Date;
    updated_at: Date;
  };
  services: {
    id: string;
    slug: string;
    area: string;
    provider_id: string;
    category_id: string | null;
    title: string;
    summary: string | null;
    image: Json | null;
    photos: Json;
    badge: string | null;
    from_price: number | null;
    currency: string;
    price_unit: string;
    duration_label: string | null;
    supported_label: string | null;
    coverage: string | null;
    tags: Json;
    description: string | null;
    included: Json;
    requirements: Json;
    supported: Json;
    os_versions: Json;
    handover: Json;
    price_table: Json;
    price_table_title: string | null;
    terms: Json;
    full_terms: string | null;
    covered_by_warranty: boolean;
    steps: Json;
    slot_minutes: number | null;
    duration_minutes: number | null;
    status: string;
    position: number;
    rating_sum: number;
    rating_count: number;
    rating_stars: Json;
    created_at: Date;
    updated_at: Date;
  };
  requests: {
    id: string;
    ref: string;
    area: string;
    service_id: string;
    provider_id: string;
    customer_id: string;
    slot_start: Date | null;
    slot_end: Date | null;
    staff_id: string | null;
    device_id: string | null;
    /** RequestDevice at the time of the request */
    device: Json | null;
    contact: Json;
    details: Json;
    status: string;
    provider_note: string | null;
    staff_note: string | null;
    history: Json;
    reviewed: boolean;
    created_at: Date;
    updated_at: Date;
  };
  reviews: {
    id: string;
    service_id: string;
    provider_id: string;
    request_id: string;
    customer_id: string;
    author_name: string;
    rating: number;
    text: string | null;
    status: string;
    created_at: Date;
  };
  /** Providers customers saved (customers-module id) */
  saved_providers: {
    id: string;
    customer_id: string;
    provider_id: string;
    created_at: Date;
  };
  /** Phones customers registered for post-sale cover (customers-module id) */
  devices: {
    id: string;
    customer_id: string;
    brand: string;
    model: string;
    storage: string | null;
    /** 15 digits */
    imei: string;
    imei_last4: string;
    purchase_date: string;
    order_ref: string | null;
    status: 'pending' | 'verified' | 'rejected';
    covered_until: string | null;
    reject_reason: string | null;
    staff_note: string | null;
    verified_at: Date | null;
    verified_by: string | null;
    history: Json;
    created_at: Date;
    updated_at: Date;
  };
}

